  "entries": [
    {
      "name_han": "咒枣记",
      "logic_thesis": "济世法力必先立于诚心与赎罪：误伤之业须以正法（咒枣）转为「自养—救病—伏魔」三位一体的功行，方能由吏医凡身证真人道果。",
      "logic_chain": "1) 前世/今生积善拒色，得天眷为修道根基；2) 入世为吏为医，心正而术未精，误投药杀人，业障显露；3) 痛悔弃官求道，遇真仙授咒枣法——一枣自食养命、一枣治病济人、一枣咒力降魔；4) 沿途试法，以有限法力优先救人伏邪，积累功行；5) 法不离德：咒术只在正心时灵验，邪用则反噬；6) 功满建供、得保举飞升，完成「罪→悔→法→济→证」闭环。",
      "logic_practice": "1) 查日主是否「先善后折」：早年印比护身，中运官杀或食伤误用致灾（如医讼、药害、口舌）；2) 见伤官见官或食伤制杀过重，断「术伤人」之象，宜改行术业为德业；3) 用神取印星或食神有制：印主悔悟求道，食神主济世咒力（咒枣=食神化气）；4) 流年财官夹印、驿马逢生时，可启动「游方试法」运，宜行善、学正术；5) 大运水火既济或金水相涵，判功行将满，名位由吏医转宗教/公益领袖。",
      "logic_compare": "与《韩湘子全传》同属「得道后反复以法度人」，但《咒枣记》重心在「误业—赎罪—咒术济世」的术德合一；较《吕祖全传》少黄粱破名，多医家伦理与咒力三用（养、救、伏）。"
    },
    {
      "name_han": "五顯靈官大帝華光天王傳",
      "logic_thesis": "神通与火性若无皈正与孝德约束，必三世轮回、闹三界；唯以救母尽孝收束业火，方能由叛神转为永镇中界、显应赐福之正神。",
      "logic_chain": "1) 本为妙吉祥/灵耀，因火性过刚（杀独火鬼等）违慈悲，贬谪转世；2) 三眼通三界，神通再大仍困于报父仇、闹龙宫、盗宝、琼花宴夺花酒等执；3) 多次转胎（马耳山、炎玄天王等）显示「才大命舛」循环；4) 核心转机为救母入地狱、闹天宫人间，以孝火压业火；5) 终皈佛/受玉封为五显灵官，火神职能转化为护民、求子、利市；6) 结论：显应不在逞强，而在「火归正位、孝满业消」。",
      "logic_practice": "1) 日主火旺或丙丁透干、羊刃劫财重，断「华光型」火性命：才高气盛、易犯上；2) 看印枭与父母宫：印受伤则有救母/护亲主题，流年冲克父母宫需防亲厄并宜行孝解；3) 官杀为用则「皈正」——武职、法门、消防/能源/司法可收火；4) 财星得火生而有制，断由争财夺名转为「一本万利」式正财显应；5) 大运由伤官见官转为印比护身，对应「闹三界→永镇中界」的格局跃迁。",
      "logic_compare": "与《北游记》真武同属「出身志传式神魔成道」，华光以火与孝救母为核心，真武以水与断内脏魔为核心；较《西游》齐天闹天，华光更强调三世转胎与民间财神/火神显应。"
    },
    {
      "name_han": "韓湘子全傳",
      "logic_thesis": "仙骨先定而亲缘难断：得道者必须以反复示现（十二度）破儒家名位执着，使眷属由拒道到同升，证明「自度必尽于度亲」。",
      "logic_chain": "1) 湘子本精灵/仙体转世，遇钟吕授道，仙籍已定；2) 叔韩愈以儒业功名养教，形成「道骨 vs 儒执」主冲突；3) 湘子隐修成道后，不以一示而足，而以十二次点化（花开顷刻、雪拥蓝关、驱鳄等）递进破执；4) 韩愈贬潮、险难是业报与机缘叠合，湘子以法护持而非改命逃避；5) 家人逐一感悟，儒道张力在「忠孝之上更有性命」处和解；6) 终度叔飞升，完成仙道伦理：度亲是功行，非拖累。",
      "logic_practice": "1) 日主有华盖、文昌、空亡或印重身轻，断「仙骨先定」之象，宜道艺而非纯科第；2) 年柱与日支六冲/刑，或官星与印交战，断叔伯/长辈儒执阻碍；3) 用神取食伤泄秀或偏印通关：食伤主仙法示现，偏印主方外师承（钟吕型）；4) 流年驿马合官、桃花带印，可作「回家点化」运，宜以实绩感化亲而非硬辩；5) 大运由官杀混杂转印比清纯，对应十二度中后期亲眷同修之象。",
      "logic_compare": "与《吕祖全传》同尊钟吕法系，但韩传专攻「一度再十二度」的家族度化节奏；较《咒枣记》少赎罪咒术，多儒道辩论与蓝关式诗谶示现。"
    },
    {
      "name_han": "綠野仙蹤",
      "logic_thesis": "弃科举名利而性命双修：内丹未成不可妄求外丹；济世除妖与朝元证位并行，出世心须用入世功来圆满。",
      "logic_chain": "1) 冷于冰见官场腐败、功名虚妄，割恩弃家求道（出世动机）；2) 久访无真，遇火龙真人试以秽物（死蛤蟆换骨丹），诚则得丹；3) 授诀：佛只修性，道则神（性）气（命）兼修，大周天与内丹次第；4) 戒「内丹未成而烧外丹坑人」；5) 得雷珠木剑葫芦后，收妖、护国、度徒，步步正路，邪则雷火碎骨；6) 功满骑鸾朝帝阙，证「绿野仙踪」——尘中修、尘中了。",
      "logic_practice": "1) 官杀重而印破、或伤官见官，断科场/仕途幻灭点，宜中年转玄修或隐业；2) 日主弱得火土通关或水火既济，取「性命双修」用神：火主神性、水主气命；3) 偏财/食神为忌而改用印比，对应吞秽试心后换骨，忌贪外丹黄白；4) 流年食伤制杀、驿马动，可任「收妖济世」类工作（危机处理、除害、公益执法）；5) 晚运印旺官清、天乙贵人夹拱，断朝元/社会尊位，非复科举之名而是德位。",
      "logic_compare": "较《吕祖全传》更写实于明清社会与师徒团队作战；较《韩湘子》少纯度亲，多冷于冰「弃家—试心—双修—雷法济世」的士人修道全景。"
    },
    {
      "name_han": "北方真武祖師玄天上帝出身志傳",
      "logic_thesis": "成道须先断内魔：脏腑阴浊外化为龟蛇精怪，唯反复下凡修武当、终伏自所弃之阴物为将，方能以北方水德镇邪，位玄天上帝。",
      "logic_chain": "1) 真武为玉帝/先天元神应化，本具神格却因凡念屡败；2) 武当苦修，弃脏腑于岩下，肚肠化龟蛇为害中界——内魔外化；3) 奉旨下凡取二物为将，实即降伏自身阴浊；4) 历经战伐、被伤、再修，证明神格亦须经历「失—悔—伏」；5) 龟蛇归顺为水火二将，阴阳既济于足下；6) 北方属水属黑，以水德克火邪、护航海与伏魔，完成玄武神格落地。",
      "logic_practice": "1) 日主坐子/亥或辰中水库，北方气重，断玄武型命：宜武镇、安保、水利、航海；2) 身中湿浊重（浊金浊水、枭印困身）而见羊刃/杀，断「脏腑化龟蛇」——疾病、抑郁、属下叛为内魔外象；3) 用神取火炼水或土止水：先清湿浊，再以杀刃为权伏内邪；4) 流年冲辰戌丑未墓库，宜「起藏伏魔」——手术、戒瘾、整顿团队；5) 大运水火既济、杀印相生，断龟蛇为将、威德双显。",
      "logic_compare": "与华光传同为余象斗「游记」体神魔出身志，真武主水德伏内魔，华光主火性收孝业；较《吕祖》剑斩三尸，真武以「自弃脏腑再收为将」更极端地示现内炼外征。"
    },
    {
      "name_han": "上洞八仙傳",
      "logic_thesis": "八门人器不同而道同：各依本命法器显通，不靠乘云混过；群仙协作可过海，但逞兴夺宝必生龙战，终须和会方太平。",
      "logic_chain": "1) 铁拐、钟离、洞宾等各以异途（病残、武贵、儒生、女身、国戚等）成道，证明根性多元；2) 师徒链（拐李度钟离、钟吕度韩曹等）与自悟者并立，无单一模板；3) 赴蟠桃归途，吕倡「各投宝物渡海」——禁止同质化神通；4) 龙子夺蓝采和玉版，因逞宝生灾；5) 八仙火烧东洋、请兵和解，示「神通过界必有制衡」；6) 结论：各显神通是个性成道，过海是协作，争宝是共业。",
      "logic_practice": "1) 八字按「器」取象：食伤为箫管花篮拍板（技艺法器），偏财为玉版，七杀为铁拐剑，印为拂尘竹罩；2) 日主强弱与通关看「能否自立一器渡海」，忌八字无主而攀云（靠他人格局）；3) 比劫重而财露，断「龙子夺宝」象，合伙易被夺，宜合同与分器；4) 流年驿马逢冲、水旺海动，是「过海」年：宜团队出差、跨界，忌一人逞宝；5) 见天德月德或合会解冲，断观音式和解运，争端宜第三方调解。",
      "logic_compare": "与单传《韩湘子》《吕祖》不同，本书逻辑是「群谱+协作过险」；较《绿野仙踪》师徒团更强调八种社会身份（男女老少富贵贫贱）皆可成仙。"
    },
    {
      "name_han": "呂祖全傳",
      "logic_thesis": "黄粱一梦破名利，十试炼心验尘浊；剑断烦恼色欲贪嗔，功行未完则混俗济世，誓「度尽众生方上升」——自度与度世同一条因果链。",
      "logic_chain": "1) 儒生求仕，长安遇钟离，黄粱梦尽示五十年荣悴一瞬；2) 悟后求度，钟离十试（死丧、赔钱、辱骂、虎、女色、盗、还金、毒、风涛、索命鬼）皆不动；3) 授黄白而拒「误五百年后之人」，此念即满三千功；4) 得灵宝毕法与火龙剑，一断烦恼二断色欲三断贪嗔；5) 不即上升，而江淮斩蛟、混迹市廛、飞鸾演化，以忠孝信仁为见吕之实；6) 心善属阳明天堂路，心恶属阴浊地狱阶——天堂地狱由心自化。",
      "logic_practice": "1) 官星与财星夹印而空亡/冲，断黄粱型：中年名利梦醒，宜弃官修道教/咨询；2) 十试对应十神考验：财试贪、官试名、杀试惧、食伤试色言、印试师约；用神稳则试过；3) 食神制杀或偏印化杀为「飞剑」用神，宜执法、外科、危机干预；4) 流年驿马合德，是混俗度人运，宜行善而不炫神通；5) 晚运印旺身健、官杀有制，断功行将圆，仍看愿力（比劫多则「度尽方升」之象）。",
      "logic_compare": "为八仙叙事之枢纽：《韩湘子》承其钟吕法脉，《何仙姑宝卷》承其点化女仙；较《咒枣记》更系统于「梦—试—剑—誓愿」四段论，是内丹伦理的总纲文本。"
    },
    {
      "name_han": "靈應泰山娘娘寶卷",
      "logic_thesis": "女身守贞修道、拒妃封而隐岱岳，证天仙玉女后以灵应司人间善恶：送子护眼延寿护国，皆依因果不昧——修福与刊经施财即感应通路。",
      "logic_chain": "1) 出身善门，幼斋悟道，拒皇召为妃，断世俗阴阳匹配；2) 泰山隐修三十二年，时间即功行量化；3) 玉封碧霞元君，永镇泰山，统眼光/子孙/送生等娘娘职能网；4) 宝卷反复：善恶分明、因果无差，灵应非贿神而是心行对位；5) 施财刊板、求子造经为「有福修福高迁一步」的操作；6) 收圆结果：女神信仰完成「个人成道→社区灵应→国泰民安」扩展。",
      "logic_practice": "1) 女命日主清、印旺官弱或官星被合，断「拒妃封」型，宜宗教慈善或独立事业，不宜纯攀附夫星；2) 子女宫（时支）见食伤生财有情，取送子娘娘象，流年食伤旺可助孕助幼；3) 用神为印与食神：印主隐修，食神主灵应施予；4) 流年天医、天德临父母/子女宫，断眼光/痘疹/护幼类救护运；5) 财星轻而逢印，宜「施财刊经」式捐赠积累福德，忌纯买香贿求。",
      "logic_compare": "与《香山宝卷》同为女神拒婚成道，泰山娘娘偏「镇岳灵应、送子护生、因果赏罚」，妙善偏「割手眼大孝成观音」；较《何仙姑宝卷》更制度化、社群化（歇马堂、刊板功德）。"
    },
    {
      "name_han": "香山寶卷",
      "logic_thesis": "大孝即大慈：违父命拒婚出家非不孝，而是以舍身（手眼）救父、化家国同皈，将血亲之孝提升为观音式无缘慈悲，故成道。",
      "logic_chain": "1) 妙善自幼持戒，立志成佛，拒妙庄王婚配——道心先于王权；2) 父怒：囚、劳役、火寺、斩首，考验意志；3) 虎负香山修炼，入冥游狱，扩慈悲至地狱众生；4) 父病需亲手眼，姐拒而妙善自剜自断，药到病除；5) 父悔率眷皈依，血亲冲突在「舍身救亲」处和解；6) 证千手千眼观音：因舍而得无限手眼，逻辑为「损己利他→神通翻倍」。",
      "logic_practice": "1) 日时食伤尽破而印在年，断「舍手眼」象：中年损财损身以救亲，反得名德；2) 官杀攻身而用印化，对应拒婚/抗父后得师救护（山神、香山）；3) 父母宫受冲克之年防亲病，宜主动医疗与行孝，忌硬顶；4) 流年伤官合杀或食神制杀，是「违命成道」窗口，宜坚持正愿；5) 大运由杀重转印旺，断由受害公主变为救苦观音位——职业向医护、社工、法务救济。",
      "logic_compare": "与《灵应泰山娘娘宝卷》同拒婚女修，香山以佛教观音果位与「割手眼」极致孝慈为核心；与《韩湘子》度亲相比，妙善是以自身残损换亲悟，强度更高、伦理更悲壮。"
    },
    {
      "name_han": "何仙姑寶卷",
      "logic_thesis": "女身仙风道骨可证上洞：吕祖反复点化，关键劝亲同修而父母执招婿靠老；须破「嫁娶传宗」之执，净身办道，方入八仙班列为女仙范型。",
      "logic_chain": "1) 何氏小姐本有仙骨毫光，吕祖佯装赎药等屡次指点；2) 女悟后劝爹娘同修，员外夫妇只图眼前快乐与招赘靠老；3) 冲突焦点：世俗以婚配延续家庭 vs 仙道以净修断尘缘；4) 吕祖再下界，以言说与法示破亲执，非强夺；5) 女坚持不嫁、修行办道，父母渐明或业缘了结；6) 何入八仙，证明女命不因「坤道」而低一等，关键在愿力与师缘。",
      "logic_practice": "1) 女命日坐空亡/华盖、印比清纯、官星弱或被冲，断仙姑型：宜迟婚或不婚修道艺；2) 年柱父母官财重，流年官星合日，断「父母逼嫁/招赘」关，宜沟通与分居清修；3) 用神取偏印与食神：偏印为吕祖式师点，食神为净体养生（桃药/素食象）；4) 驿马逢印之年是点化年，遇方外师或宗教文本则契；5) 大运由财官转向印比，对应「辞婚—同修—列仙」，事业宜医药、养生、女众教育。",
      "logic_compare": "与《香山宝卷》《泰山娘娘宝卷》同属女拒婚成圣谱系，何仙姑更嵌入八仙群体与吕祖度人网；较妙善少割肉酷烈，多「反复点化+劝亲」的日常伦理张力，更贴近民间宝卷劝善。"
    }
  ]
}
